<?php
require_once 'config.php';require_login();$pageTitle='Jenis Pelanggaran';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$act=$_POST['action']??'';if($act==='save'){$id=(int)($_POST['id_jenis']??0);$nama=trim($_POST['nama_jenis']??'');$poin=max(0,(int)($_POST['poin']??0));$ket=trim($_POST['keterangan']??'');if(!$nama)$error='Nama jenis wajib diisi.';else{if($id){$st=$pdo->prepare('UPDATE jenis_pelanggaran SET nama_jenis=?,poin=?,keterangan=? WHERE id_jenis=?');$st->execute([$nama,$poin,$ket,$id]);}else{$st=$pdo->prepare('INSERT INTO jenis_pelanggaran(nama_jenis,poin,keterangan) VALUES(?,?,?)');$st->execute([$nama,$poin,$ket]);}header('Location: jenis.php?ok=1');exit;}}if($act==='delete'&&is_admin()){try{$st=$pdo->prepare('DELETE FROM jenis_pelanggaran WHERE id_jenis=?');$st->execute([(int)$_POST['id_jenis']]);header('Location: jenis.php?ok=1');exit;}catch(PDOException $e){$error='Jenis ini sudah dipakai dalam catatan pelanggaran.';}}}$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM jenis_pelanggaran WHERE id_jenis=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$rows=$pdo->query('SELECT j.*,COUNT(p.id_pelanggaran) jumlah FROM jenis_pelanggaran j LEFT JOIN pelanggaran p ON p.id_jenis=j.id_jenis GROUP BY j.id_jenis ORDER BY j.nama_jenis')->fetchAll();include 'partials/header.php';?>
<?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['ok'])):?><div class="alert success">Data berhasil diproses.</div><?php endif;?><div class="panel"><div class="panel-head"><div><h3><?=$edit?'Edit Jenis':'Tambah Jenis Pelanggaran'?></h3><p>Atur kategori dan bobot poin pelanggaran.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="action" value="save"><input type="hidden" name="id_jenis" value="<?=e($edit['id_jenis']??'')?>"><div><label>Nama Jenis *</label><input name="nama_jenis" required value="<?=e($edit['nama_jenis']??'')?>" placeholder="Misalnya: Terlambat datang"></div><div><label>Poin</label><input type="number" min="0" name="poin" required value="<?=e($edit['poin']??5)?>"></div><div class="wide"><label>Keterangan</label><textarea name="keterangan" rows="2"><?=e($edit['keterangan']??'')?></textarea></div><div class="wide"><button class="btn primary">Simpan Jenis</button> <?php if($edit):?><a class="btn" href="jenis.php">Batal</a><?php endif;?></div></form></div><div class="panel"><div class="panel-head"><h3>Daftar Jenis Pelanggaran</h3></div><div class="table-wrap"><table><thead><tr><th>Jenis</th><th>Poin</th><th>Keterangan</th><th>Jumlah Catatan</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['nama_jenis'])?></b></td><td><?= (int)$r['poin'] ?></td><td><?=e($r['keterangan'])?></td><td><?=$r['jumlah']?></td><td><a class="link" href="?edit=<?=$r['id_jenis']?>">Edit</a> <?php if(is_admin()):?><form class="inline" method="post" onsubmit="return confirm('Hapus jenis ini?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id_jenis" value="<?=$r['id_jenis']?>"><button class="link red">Hapus</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php include 'partials/footer.php';?>
